async function boot(){
  const page=document.body.dataset.page||'home';
  const handlers={home:initHome,dataset:initDataset,explore:initExplore,matrix:initMatrix,dashboard:initDashboard,tracker:initTracker,reviewqueue:initReviewQueue,today:initToday,contacts:initContacts,documents:initDocuments,analytics:initAnalytics,quality:initQuality,africamap:initAfricaMap,settings:initSettings,checker:initLinkChecker,admin:initAdmin,notfound:initNotFound,sources:initSources,sourceintel:initSourceIntelligence,ats:initATSConnectors,capture:initCapture,calendar:initCalendar,versions:initVersionHistory,weekly:initWeeklyReview,tracks:initOpportunityTracks,consulting:initConsulting,rosters:initRosters,volunteer:initVolunteerSecondments,requirements:initRequirements,templates:initTemplates,emailimport:initEmailImporter,profilecoverage:initProfileCoverage,rules:initRules,archive:initArchive,vault:initVault};
  await (handlers[page]||initHome)();applyTranslations();
}

function loader(target,msg='Loading career intelligence…',cancel=false){target.innerHTML=`<div class="loading"><span class="spinner"></span><p>${escapeHTML(msg)}</p>${cancel?'<button class="button secondary" id="cancelLargeLoad">Cancel loading</button>':''}</div>`;if(cancel)document.getElementById('cancelLargeLoad')?.addEventListener('click',()=>{releaseFilterWorker();location.href='./index.html'})}
function fatal(error){console.error(error);const main=$('main')||document.body;main.innerHTML=`<section class="page"><div class="error-state"><h1>Unable to load the project</h1><p>${escapeHTML(error.message||error)}</p><button class="button primary" id="fatalRetry">Retry</button></div></section>`;$('#fatalRetry')?.addEventListener('click',()=>location.reload())}

