function startCard(icon,title,desc,page,kind=''){return `<a class="start-card ${kind}" href="./${page}"><span class="start-icon">${escapeHTML(icon)}</span><div><strong>${escapeHTML(title)}</strong><p>${escapeHTML(desc)}</p><em>${getLanguage()==='ar'?'فتح':'Open'} →</em></div></a>`}
function compactLink(page,label){return `<a href="./${page}">${escapeHTML(label)} <span>→</span></a>`}
function moduleCard(key,d){return `<a class="module-card" href="./${d.page}"><div class="module-icon">${escapeHTML(d.icon)}</div><div class="module-copy"><strong>${getLanguage()==='ar'?d.labelAr:d.label}</strong><span>${d.target.toLocaleString()} ${t('records')}</span><p>${moduleDescription(key)}</p></div><span class="module-arrow">→</span></a>`}
function moduleDescription(key){const ar=getLanguage()==='ar';const map={ngos:["Humanitarian, development, African and multilateral organizations working across the continent","منظمات إنسانية وتنموية وأفريقية ودولية تعمل في القارة"],organizations:["ICT employers, NGOs, vendors and institutions","جهات تقنية ومنظمات دولية وشركات حلول"],medical:["Pharma, medtech, hospitals and digital health","أدوية وأجهزة طبية ومستشفيات وصحة رقمية"],recruitment:["Recruiters, executive search and job platforms","وكالات توظيف وبحث تنفيذي ومنصات وظائف"],government:["Official public-sector employment gateways","بوابات التوظيف الحكومية والرسمية"],companies:["Major employers across Arab and African markets","شركات كبرى في الأسواق العربية والأفريقية"],egypt:["Named and live searches across Egypt","وظائف مسماة وبحث حي داخل مصر"],gcc:["Saudi, UAE, Qatar, Kuwait, Oman and Bahrain","السعودية والإمارات وقطر والكويت وعُمان والبحرين"],remote:["Worldwide, EMEA and region-compatible remote work","فرص عالمية وعن بُعد مع توضيح الأهلية"],jobs:["Combined named jobs and monitored live searches","قاعدة موحدة للوظائف والبحث الحي"],platforms:["Verified official, specialist, African, MENA and remote sources","مصادر رسمية ومتخصصة وأفريقية وعربية وعن بُعد"],projects:["Tenders, EOIs, RFPs and consulting searches","مناقصات وطلبات عروض وفرص استشارية"]};return map[key]?.[ar?1:0]||''}
function bindHomeSearch(){
  $('#homeSearchForm')?.addEventListener('submit',e=>{e.preventDefault();const q=$('#homeQuery').value.trim();location.href=q?`./explore.html?q=${encodeURIComponent(q)}`:'./explore.html'});
}
async function initDataset(){
  state.dataset=document.body.dataset.dataset;
  const config=DATASETS[state.dataset];if(!config)throw new Error('Dataset configuration not found');
  const main=$('main');
  main.innerHTML=`<section class="dataset-hero ${state.dataset==='ngos'?'africa-hero':''}"><div><span class="eyebrow dark">${escapeHTML(config.kind)} directory</span><h1>${getLanguage()==='ar'?config.labelAr:config.label}</h1><p>${moduleDescription(state.dataset)}</p>${state.dataset==='ngos'?africaQuickLinks():''}</div><div class="hero-actions"><a class="button secondary" href="./explore.html?dataset=${state.dataset}">${getLanguage()==='ar'?'بحث موسع':'Search this category'}</a><button class="button primary" id="refreshData">${t('refresh')}</button></div></section><section id="datasetStats" class="summary-grid"></section>${workspaceHTML()}`;
  loader($('#resultArea'));state.records=await loadDataset(state.dataset);state.filtered=[...state.records];populateFilters();bindWorkspace();if(state.dataset==='platforms'&&$('#sortFilter'))$('#sortFilter').value='official';const params=new URLSearchParams(location.search);if(params.get('country')&&$('#countryFilter'))$('#countryFilter').value=params.get('country');if(params.get('region')){const wanted=params.get('region');if($('#africaRegionFilter')&&[...$('#africaRegionFilter').options].some(o=>o.value===wanted))$('#africaRegionFilter').value=wanted;else if($('#regionFilter')&&[...$('#regionFilter').options].some(o=>o.value===wanted))$('#regionFilter').value=wanted}applyFilter();renderDatasetStats();
  $('#refreshData').onclick=async()=>{clearDataCache();loader($('#resultArea'),'Refreshing source data…');state.records=await loadDataset(state.dataset,{force:true});populateFilters(true);applyFilter();renderDatasetStats();showToast('Data refreshed')};
}
function workspaceHTML(){
  const global=state.dataset==='global',ngos=state.dataset==='ngos'||global,settings=getSettings();
  return `<section class="search-presets" id="searchPresets">${SEARCH_PRESETS.map(p=>`<button type="button" data-preset="${escapeHTML(p.id)}">${escapeHTML(getLanguage()==='ar'?p.nameAr:p.name)}</button>`).join('')}</section><section class="simple-workspace"><section class="simple-filter-bar"><label class="search-wide"><span>${t('search')}</span><div class="input-with-icon"><span aria-hidden="true">⌕</span><input id="textFilter" placeholder="${t('searchPlaceholder')}"></div><small>${getLanguage()==='ar'?'يدعم المسميات القريبة مثل Systems Manager وHead of IT':'Includes related titles such as Systems Manager and Head of IT'}</small></label>${global?`<label><span>${t('dataset')}</span><select id="datasetFilter"><option value="">${t('all')}</option></select></label>`:''}<label><span>${t('country')}</span><select id="countryFilter"><option value="">${t('all')}</option></select></label><label><span>${t('type')}</span><select id="typeFilter"><option value="">${t('all')}</option></select></label><button class="button secondary clear-button" id="clearFilters">${t('clear')}</button><details class="advanced-filters"><summary>${getLanguage()==='ar'?'فلاتر إضافية':'Additional filters'} <span>⌄</span></summary><div class="advanced-filter-grid"><label><span>${t('region')}</span><select id="regionFilter"><option value="">${t('all')}</option></select></label>${ngos?`<label><span>${getLanguage()==='ar'?'تصنيف منظمات أفريقيا':'Africa organization category'}</span><select id="africaCategoryFilter"><option value="">${t('all')}</option></select></label><label><span>${getLanguage()==='ar'?'الإقليم الأفريقي':'Africa region'}</span><select id="africaRegionFilter"><option value="">${t('all')}</option></select></label>`:''}<label><span>${getLanguage()==='ar'?'مسار الفرصة':'Opportunity track'}</span><select id="trackFilter"><option value="">${t('all')}</option>${OPPORTUNITY_TRACKS.map(x=>`<option value="${escapeHTML(x.id)}">${escapeHTML(getLanguage()==='ar'?x.nameAr:x.name)}</option>`).join('')}</select></label><label><span>${t('fit')}</span><select id="fitFilter"><option value="">${t('all')}</option><option value="75">75%+</option><option value="85">85%+</option></select></label><label><span>Vacancy / directory status</span><select id="availabilityFilter"><option value="">${t('all')}</option></select></label><label><span>${t('myStatus')}</span><select id="personalStatusFilter"><option value="">${t('all')}</option><option>Not started</option><option>Saved</option><option>Job Found</option><option>Planning to Apply</option><option>Applied</option><option>Assessment</option><option>Interview</option><option>Follow-up</option><option>Offer</option><option>Rejected</option><option>Not Available</option><option value="Recheck Due">${getLanguage()==='ar'?'حان موعد إعادة المراجعة':'Recheck Due'}</option><option>Closed</option></select></label><label><span>Egypt eligibility</span><select id="eligibilityFilter"><option value="">${t('all')}</option><option value="eligible">Eligible from Egypt</option><option value="likely">Likely eligible</option><option value="unclear">Unclear</option><option value="restricted">Likely not eligible</option></select></label><label><span>Freshness</span><select id="freshnessFilter"><option value="">${t('all')}</option><option value="fresh">Fresh — 0–30 days</option><option value="aging">Aging — 31–60 days</option><option value="old">Old — 61–90 days</option><option value="stale">Stale — 90+ days</option></select></label><label><span>${t('sort')}</span><select id="sortFilter"><option value="official" ${settings.officialSourcesFirst?'selected':''}>Official sources first</option><option value="match" ${!settings.officialSourcesFirst?'selected':''}>${t('bestMatch')}</option><option value="newest">${t('newest')}</option><option value="priority">Organization priority</option><option value="name">${t('name')}</option></select></label><label class="checkbox"><input type="checkbox" id="favoriteOnly"> ${t('favoriteOnly')}</label><label class="checkbox"><input type="checkbox" id="hideClosed"> ${t('hideClosed')}</label><label class="checkbox"><input type="checkbox" id="applyExclusions" ${settings.exclusions?.length?'checked':''}> Apply permanent exclusions (${settings.exclusions?.length||0})</label><button class="button secondary" id="exportCsv">${t('exportCsv')}</button><a class="button secondary" href="./settings.html">Search settings</a></div></details></section><section class="results-panel"><div class="results-toolbar"><div><h2 id="resultTitle">${t('results')}</h2><p id="resultCount"></p></div><div class="view-switch"><button class="icon-button ${state.view==='grid'?'active':''}" data-view="grid" aria-label="Comfortable cards">▦</button><button class="icon-button ${state.view==='compact'?'active':''}" data-view="compact" aria-label="Compact cards">▤</button><button class="icon-button ${state.view==='table'?'active':''}" data-view="table" aria-label="${t('viewTable')}">☷</button></div></div><div id="resultArea"></div><nav class="pagination" id="pagination" aria-label="Pagination"></nav></section></section>`
}
function africaQuickLinks(){return `<div class="africa-quick-links"><a href="https://reliefweb.int/jobs" target="_blank" rel="noopener">ReliefWeb jobs ↗</a><a href="https://www.devex.com/jobs/search?locations%5B%5D=Africa" target="_blank" rel="noopener">Devex Africa ↗</a><a href="https://www.impactpool.org/countries" target="_blank" rel="noopener">Impactpool ↗</a></div>`}
function populateFilters(reset=false){
  const populate=(id,values,labels=null)=>{const select=$(id);if(!select)return;const current=select.value;select.innerHTML=`<option value="">${t('all')}</option>`+[...new Set(values.filter(Boolean))].sort().map(x=>`<option value="${escapeHTML(x)}">${escapeHTML(labels?.[x]||x)}</option>`).join('');select.value=current};
  if(state.dataset==='global')populate('#datasetFilter',state.records.map(x=>x.dataset),Object.fromEntries(Object.entries(DATASETS).map(([k,v])=>[k,getLanguage()==='ar'?v.labelAr:v.label])));
  populate('#countryFilter',state.records.map(x=>x.country));populate('#regionFilter',state.records.map(x=>x.region));populate('#typeFilter',state.records.map(x=>x.type));populate('#availabilityFilter',state.records.map(x=>x.availability));populate('#africaCategoryFilter',state.records.map(x=>x.africaCategory));populate('#africaRegionFilter',state.records.map(x=>x.africaRegion));
}
function bindWorkspace(){
  ['#textFilter','#datasetFilter','#countryFilter','#regionFilter','#typeFilter','#fitFilter','#availabilityFilter','#personalStatusFilter','#africaCategoryFilter','#africaRegionFilter','#freshnessFilter','#eligibilityFilter','#trackFilter','#sortFilter','#favoriteOnly','#hideClosed','#applyExclusions'].forEach(id=>$(id)?.addEventListener(id==='#textFilter'?'input':'change',()=>{state.page=1;applyFilter()}));
  $('#searchPresets')?.addEventListener('click',e=>{const id=e.target.dataset.preset;if(!id)return;const p=SEARCH_PRESETS.find(x=>x.id===id);if(!p)return;$('#textFilter').value=p.query;if(p.filters.dataset&&$('#datasetFilter'))$('#datasetFilter').value=p.filters.dataset;state.page=1;applyFilter()});
  if($('#clearFilters'))$('#clearFilters').onclick=()=>{['#textFilter','#datasetFilter','#countryFilter','#regionFilter','#typeFilter','#fitFilter','#availabilityFilter','#personalStatusFilter','#africaCategoryFilter','#africaRegionFilter','#freshnessFilter','#eligibilityFilter','#trackFilter'].forEach(id=>{if($(id))$(id).value=''});$('#sortFilter').value='match';$('#favoriteOnly').checked=false;$('#hideClosed').checked=false;state.page=1;applyFilter()};
  if($('#exportCsv'))$('#exportCsv').onclick=()=>{const rows=state.filtered.map(r=>({...r,myStatus:getTracking(r).status,reviewAgain:getTracking(r).reviewAgain,reviewReason:getTracking(r).reviewReason,linkStatus:getLinkCheck(r)?.state||'Unknown',freshness:dataFreshness(r,getLinkCheck(r)).label,careersLinkQuality:careersLinkQuality(r).label}));downloadFile(`${state.dataset||'career'}-filtered.csv`,toCSV(rows),'text/csv;charset=utf-8')};
  $$('.view-switch button').forEach(btn=>btn.onclick=()=>{state.view=btn.dataset.view;localStorage.setItem('career-view',state.view);$$('.view-switch button').forEach(x=>x.classList.toggle('active',x===btn));renderResults()});
}
async function applyFilter(){
  const token=(state.filterToken||0)+1;state.filterToken=token;
  const q=($('#textFilter')?.value||'').trim(),dataset=$('#datasetFilter')?.value||'',country=$('#countryFilter')?.value||'',region=$('#regionFilter')?.value||'',type=$('#typeFilter')?.value||'',fit=Number($('#fitFilter')?.value||0),availability=$('#availabilityFilter')?.value||'',personal=$('#personalStatusFilter')?.value||'',africaCategory=$('#africaCategoryFilter')?.value||'',africaRegion=$('#africaRegionFilter')?.value||'',freshness=$('#freshnessFilter')?.value||'',favorites=$('#favoriteOnly')?.checked,hide=$('#hideClosed')?.checked,applyExclusions=$('#applyExclusions')?.checked,sort=$('#sortFilter')?.value||'match',eligibility=$('#eligibilityFilter')?.value||'',track=$('#trackFilter')?.value||'';
  state.query=q;state.filters={dataset,country,region,type,fit,availability,personal,africaCategory,africaRegion,freshness,eligibility,track};
  const canUseWorker=state.records.length>5000&&!personal&&!freshness&&!favorites&&!applyExclusions&&!eligibility&&!track&&sort!=='priority';
  if(canUseWorker){
    $('#resultCount').textContent='Filtering large dataset…';
    const result=await filterLargeDataset(state.records,{query:q,dataset,country,region,typeValue:type,fit,availability,africaCategory,africaRegion,hideClosed:hide,sort});
    if(token!==state.filterToken)return;state.filtered=result;
  }else{
    state.filtered=state.records.filter(r=>{const tracking=getTracking(r),fresh=dataFreshness(r,getLinkCheck(r)),personalMatch=!personal||(personal==='Recheck Due'?isRecheckDue(tracking):tracking.status===personal),eligibilityMatch=!eligibility||(r.eligibility?.key||'unclear')===eligibility,trackMatch=!track||detectOpportunityTrack(r).id===track;return matchesSearch(r,q)&&(!applyExclusions||!matchesExclusions(r))&&(!dataset||r.dataset===dataset)&&(!country||r.country===country)&&(!region||r.region===region)&&(!type||r.type===type)&&(!fit||r.profileMatch>=fit)&&(!availability||r.availability===availability)&&personalMatch&&eligibilityMatch&&trackMatch&&(!africaCategory||r.africaCategory===africaCategory)&&(!africaRegion||r.africaRegion===africaRegion)&&(!freshness||fresh.key===freshness)&&(!favorites||isFavorite(r))&&(!hide||r.availability!=='Deadline Passed')});
    state.filtered.sort((a,b)=>sort==='priority'?organizationPriority(b,getTracking(b),getLinkCheck(b)).score-organizationPriority(a,getTracking(a),getLinkCheck(a)).score:sort==='official'?sourceAuthorityRank(b)-sourceAuthorityRank(a)||b.profileMatch-a.profileMatch:sort==='name'?a.title.localeCompare(b.title):sort==='newest'?(Date.parse(b.posted||b.checked)||0)-(Date.parse(a.posted||a.checked)||0):b.profileMatch-a.profileMatch||b.trustScore-a.trustScore);
  }
  state.page=1;renderResults();
}

function renderResults(){
  const start=(state.page-1)*PAGE_SIZE,rows=state.filtered.slice(start,start+PAGE_SIZE),area=$('#resultArea');$('#resultCount').textContent=`${state.filtered.length.toLocaleString()} ${t('results')}`;
  if(!rows.length){const suggestions=emptyStateSuggestions(state.query,state.filters);area.innerHTML=`<div class="empty-state enhanced-empty"><h3>${t('noResults')}</h3><p>${getLanguage()==='ar'?'الفلاتر الحالية لم تنتج نتائج. جرّب أحد الاقتراحات:':'The current filters produced no results. Try one of these:'}</p><div>${suggestions.map((x,i)=>`<button class="button secondary" data-empty-action="${i}">${escapeHTML(x)}</button>`).join('')}</div><button class="button primary" id="emptyClear">${t('clear')}</button></div>`;$('#pagination').innerHTML='';$('#emptyClear').onclick=()=>$('#clearFilters').click();return}
  if(state.view==='table')area.innerHTML=renderTable(rows);else{area.innerHTML=`<div class="result-grid ${state.view==='compact'?'compact-grid':''}">${rows.map(r=>renderCard(r,{query:state.query,compact:state.view==='compact'})).join('')}</div>`;bindCards(area,rows,()=>renderResults())}renderPagination();
}
function renderPagination(){const pages=Math.ceil(state.filtered.length/PAGE_SIZE),nav=$('#pagination');if(pages<=1){nav.innerHTML='';return}const nums=new Set([1,pages,state.page-2,state.page-1,state.page,state.page+1,state.page+2]);const list=[...nums].filter(n=>n>=1&&n<=pages).sort((a,b)=>a-b);let last=0;nav.innerHTML=`<button ${state.page===1?'disabled':''} data-page="${state.page-1}">${t('previous')}</button>`+list.map(n=>{const gap=n-last>1?'<span>…</span>':'';last=n;return `${gap}<button class="${n===state.page?'active':''}" data-page="${n}">${n}</button>`}).join('')+`<button ${state.page===pages?'disabled':''} data-page="${state.page+1}">${t('next')}</button>`;nav.onclick=e=>{const p=Number(e.target.dataset.page);if(p){state.page=p;renderResults();$('.results-panel').scrollIntoView({behavior:'smooth'})}}}
