  const priority=[...all].filter(x=>x.recordType==='job'||x.recordType==='project').sort((a,b)=>b.profileMatch-a.profileMatch||b.trustScore-a.trustScore).slice(0,8);$('#priorityRecords').innerHTML=priority.map(r=>renderCard(r,{compact:true})).join('');bindCards($('#priorityRecords'),priority,()=>renderDashboard());
